function todoReducer(todos, action) {
  switch (action.type) {
    case "tambah":
      return [...todos, { id: action.id, selesai: false }];
    case "toggle":
      return todos.map((t) =>
        t.id === action.id ? { ...t, selesai: !t.selesai } : t
