solution.code:
const initialState = { items: [] };

function keranjangReducer(state, action) {
  switch (action.type) {
    case "tambah": {
      const jumlah = action.jumlah ?? 1;
      const ada = state.items.some((it) => it.id === action.id);
      return {
        ...state,
        items: ada
          ? state.items.map((it) => (it.id === action.id ? { ...it, jumlah: it.jumlah + jumlah } : it))
          : [...state.items, { id: action.id, jumlah }],
      };
    }
    case "kurangi":
      return {
        ...state,
        items: state.items
          .map((it) => (it.id === action.id ? { ...it, jumlah: it.jumlah - 1 } : it))
          .filter((it) => it.jumlah > 0),
      };
    case "hapus":
      return { ...state, items: state.items.filter((it) => it.id !== action.id) };
    case "kosongkan":
      return { ...state, items: [] };
    default:
      return state;
  }
}

function totalItem(state) {
  return state.items.reduce((total, it) => total + it.jumlah, 0);
}

function totalHarga(state, produk, diskon = 0) {
  const subtotal = state.items.reduce((total, it) => {
    const p = produk.find((x) => x.id === it.id);
    return p ? total + p.harga * it.jumlah : total;
  }, 0);
  return Math.round((subtotal * (100 - diskon)) / 100);
}

function formatRupiah(angka) {
  return new Intl.NumberFormat("id-ID", {
    style: "currency",
    currency: "IDR",
    minimumFractionDigits: 0,
    maximumFractionDigits: 0,
  }).format(angka);
}

async function muatProduk(fetcher) {
  try {
    const data = await fetcher();
    if (!Array.isArray(data)) return { status: "gagal", pesan: "Format data tidak valid" };
    return { status: "sukses", data };
  } catch (e) {
    return { status: "gagal", pesan: e.message };
  }
}

