solution.code:
function tambahTugas(list, id, judul) {
  return [...list, { id, judul, selesai: false }];
}

function toggleTugas(list, id) {
  return list.map((t) => (t.id === id ? { ...t, selesai: !t.selesai } : t));
}

function hapusTugas(list, id) {
  return list.filter((t) => t.id !== id);
}

function sisaTugas(list) {
  return list.filter((t) => !t.selesai).length;
}

