function Label() {
  const w = useContext(Warna);
  return <span>{w} </span>;
}

function App() {
  return (
    <>
      <Label />
      <Warna.Provider value="biru">
        <Label />
        <Warna.Provider value="hijau">
          <Label />
        </Warna.Provider>
      </Warna.Provider>
    </>
  );
}

