solution.code:
function keranjangReducer(state, action) {
  switch (action.type) {
    case "tambah": {
      const ada = state.items.some((it) => it.id === action.produk.id);
      const items = ada
        ? state.items.map((it) => (it.id === action.produk.id ? { ...it, jumlah: it.jumlah + 1 } : it))
        : [...state.items, { ...action.produk, jumlah: 1 }];
      return { ...state, items };
    }
    case "hapus":
      return { ...state, items: state.items.filter((it) => it.id !== action.id) };
    case "ubahJumlah":
      if (action.jumlah <= 0) return { ...state, items: state.items.filter((it) => it.id !== action.id) };
      return { ...state, items: state.items.map((it) => (it.id === action.id ? { ...it, jumlah: action.jumlah } : it)) };
    case "kosongkan":
      return { ...state, items: [] };
    default:
      return state;
  }
}

function totalHarga(state) {
  return state.items.reduce((t, it) => t + it.harga * it.jumlah, 0);
}

