solution.code:
function tambahTugas(daftar, judul, id) {
  const bersih = judul.trim();
  if (!bersih) return daftar;
  return [...daftar, { id, judul: bersih, selesai: false }];
}

function toggleTugas(daftar, id) {
  return daftar.map((t) => (t.id === id ? { ...t, selesai: !t.selesai } : t));
}

function hapusTugas(daftar, id) {
  return daftar.filter((t) => t.id !== id);
}

function saringTugas(daftar, filter) {
  if (filter === 'aktif') return daftar.filter((t) => !t.selesai);
  if (filter === 'selesai') return daftar.filter((t) => t.selesai);
  return daftar;
}

function hitungSisa(daftar) {
  return daftar.filter((t) => !t.selesai).length;
}

